function loaded(element){return new Promise((resolve,reject)=>{
 const cleanup=()=>{clearTimeout(timer);element.removeEventListener('loadedmetadata',done);element.removeEventListener('error',failed);};
 const done=()=>{cleanup();resolve();};
 const failed=()=>{const code=element.error?.code||0;cleanup();const reasons={1:'読み込みが中断されました。',2:'ファイルを取得できませんでした。',3:'映像・音声のデータを解読できませんでした。',4:'この端末で対応していない形式、または読み取れないファイルです。'};reject(Error('動画・音声を読み込めませんでした。'+(reasons[code]||'ファイルの状態を確認してください。')+'（読込コード '+code+'）'));};
 const timer=setTimeout(()=>{cleanup();reject(Error('動画の読み込みが30秒以内に完了しませんでした。端末に保存済みの動画で再度お試しください。（読込タイムアウト）'));},30000);
 element.addEventListener('loadedmetadata',done,{once:true});element.addEventListener('error',failed,{once:true});if(element.error)failed();else if(element.readyState>=1)done();
});}
async function finiteDuration(element){if(Number.isFinite(element.duration))return element.duration;await new Promise(resolve=>{const done=()=>{clearTimeout(timer);element.removeEventListener('seeked',done);resolve();},timer=setTimeout(done,3000);element.addEventListener('seeked',done,{once:true});try{element.currentTime=1e10;}catch{done();}});const duration=element.duration;try{element.currentTime=0;}catch{}return duration;}

