  const explanations={split:'再生位置でクリップを分割', 'mode-video':'映像のカット・速度・音量など','mode-audio':'音声の追加・録音・効果','mode-caption':'文字や字幕を追加・編集','mode-effects':'モザイク・ぼかしを追加','mode-materials':'画像・スタンプなどの素材を追加','mode-output':'端末への保存設定','extra-video-volume':'選択した動画クリップの音量','extra-audio-volume':'選択した音声クリップの音量','mic-start':'3秒のカウントダウン後に録音開始','mode-audio-fx':'フェード・リバーブ・ディレイなど','text-option-style':'文字の色とサイズを調整'};
  const hintButton=e=>{const b=e.target.closest('button');return b&&b.closest(menus)?b:null;};
  for(const menu of dialog.querySelectorAll(menus))for(const b of menu.querySelectorAll('button')){const name=b.querySelector('span')?.textContent||b.textContent;b.title=explanations[b.dataset.ve]||name;b.setAttribute('aria-label',b.title);}
  function showToolHint(button){const b=button.getBoundingClientRect(),d=dialog.getBoundingClientRect();toolHint.textContent=button.title;toolHint.hidden=false;toolHint.style.left=Math.max(8,Math.min(d.width-248,b.left-d.left))+'px';toolHint.style.top=Math.max(8,b.top-d.top-toolHint.offsetHeight-10)+'px';clearTimeout(hintHide);hintHide=setTimeout(()=>toolHint.hidden=true,2500);}
  dialog.addEventListener('pointerdown',e=>{const b=hintButton(e);if(!b)return;hintPress={id:e.pointerId,x:e.clientX,y:e.clientY};clearTimeout(hintTimer);hintTimer=setTimeout(()=>{showToolHint(b);hintSuppressUntil=performance.now()+3000;},500);});
