dialog.addEventListener('close',()=>{keyboardEvents.abort();timelineResize.disconnect();cancelAnimationFrame(timelineSeekFrame);clearTimeout(projectTimer);clearInterval(audioLevelTimer);window.removeEventListener('pagehide',persistProjectNow);},{once:true});dialog.oncancel=e=>{e.preventDefault();e.stopPropagation();if(dialog.classList.contains('is-preview-fullscreen')){$('[data-ve=fullscreen]').click();return;}if(detail.open){detail.open=false;return;}status.textContent='編集を終了するときは左上の「完了」を押してください。';};dialog.showModal();fitEditorViewport();if(video.readyState<2){try{video.currentTime=.001;}catch{}}const fitZoom=Math.max(2,(timelineScroll.clientWidth-18)/Math.max(.1,length()));zoom=Math.min(3600,Math.max(72,fitZoom*1.7));const zoomInput=$('.ve-zoom');zoomInput.min=String(Math.max(2,fitZoom/4));zoomInput.max='3600';zoomInput.step='any';zoomInput.value=String(zoom);controls();history.push(captureEdit());historyReady=true;syncUndoButtons();window.addEventListener('pagehide',persistProjectNow);void checkProjectRecovery();video.addEventListener('loadeddata',()=>{if(!thumbs.some(Boolean)){const frame=grabThumb(video);if(frame){thumbs[0]=frame;makeTrack();}}},{once:true});setTimeout(()=>{if(dialog.isConnected)buildThumbs();},350);
